-- Airports' elevations (metres above sea level), for flights' heights above their runways
-- rather than above the sea: FR24 gives barometric altitude, so an aircraft approaching an
-- airport 200 m up otherwise seemed to land 200 m above its runway, then drop to it.
-- From OurAirports (elevation_ft, public domain), for the airports of base_data/airports.csv by
-- ident, and the airports added since that OurAirports has (by ICAO code).
ALTER TABLE airports ADD COLUMN IF NOT EXISTS elevation_m double precision;

